package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
)

func main() {
	p, _ := filepath.Abs(os.Args[1])
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, p, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("ERR: %v\n", err)
	}
	if f != nil {
		fmt.Printf("f != nil, Name=%v, decls=%d, imports=%d, comments=%d\n", f.Name, len(f.Decls), len(f.Imports), len(f.Comments))
		ast.Print(fset, f.Name)
	} else {
		fmt.Println("f == nil")
	}
}
EOF
